#include <set>
#include <iostream>

int main() {
    std::set<int> s = {10, 20, 30};

    // Get an iterator to 20
    auto it_20 = s.find(20);

    // Insert 40. This does NOT invalidate it_20.
    s.insert(40);

    // Dereferencing the stable iterator is safe
    std::cout << "Iterator still points to: " << *it_20 << std::endl;

    // Erase 10. This does NOT invalidate it_20.
    s.erase(10);

    std::cout << "Iterator still points to: " << *it_20 << std::endl;

    // auto it_30 = s.find(30);
    // s.erase(it_30); // Iterator it_30 is now invalid!
}
